INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Sundalong Kanin', 'Sundalong Kanin', 'sundalong-kanin-2014', 'Set in 1941, the film follows Nitoy, Benny, Carding, and Badong, four boys from the quiet town of San Nicolas whose lives are transformed when World War II reaches the Philippines. Determined to prove they are no longer children, they join the resistance with makeshift weapons despite warnings that war is not for boys. As the Japanese occupation begins, their innocence is tested by the realities of war.', '2014-01-01', 2014, 'assets/sundalo.jpg', 'https://letterboxd.com/film/rice-soldiers/', '{"cinemalaya","indie","drama","crime","family","war"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
