INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Nuwebe', 'Nuwebe', 'nuwebe-2013', 'Nuwebe follows nine-year-old Krista, who becomes pregnant after being sexually abused by her own father. Rather than allowing herself to be defined by her trauma, Krista shows remarkable resilience as she struggles to rebuild her life, while her mother is torn between protecting her daughter and remaining loyal to her husband.', '2013-01-01', 2013, 'assets/nuwebe.jpg', NULL, '{"cinemalaya","indie"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
