INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Transit', 'Transit', 'transit-2013', 'It tells the story of Moises, a Filipino single-dad working as a caregiver in Herzliya, Israel, who comes home to his apartment in Tel Aviv to celebrate his son Joshua’s 4th birthday. It is on that day that Moises, together with their Filipino neighbors Janet and her daughter Yael, finds out that the Israeli government is going to deport children of foreign workers.', '2013-01-01', 2013, 'assets/transit.jpg', NULL, '{"cinemalaya","indie"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
